import java.util.ArrayDeque;
import java.util.Queue;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.ReentrantLock;

public class Main {
    static final class SafeCounter {
        private final ReentrantLock lock = new ReentrantLock();
        private int value;

        void incrementTwice() {
            lock.lock();
            try {
                value++;
                nestedIncrement();
            } finally {
                lock.unlock();
            }
        }

        private void nestedIncrement() {
            lock.lock();
            try {
                assert lock.getHoldCount() == 2;
                value++;
            } finally {
                lock.unlock();
            }
        }

        int get() {
            lock.lock();
            try {
                return value;
            } finally {
                lock.unlock();
            }
        }
    }

    static final class BoundedBox {
        private final ReentrantLock lock = new ReentrantLock();
        private final Condition notFull = lock.newCondition();
        private final Condition notEmpty = lock.newCondition();
        private final Queue<Integer> queue = new ArrayDeque<>();
        private final int capacity;

        BoundedBox(int capacity) {
            this.capacity = capacity;
        }

        void put(int value) throws InterruptedException {
            lock.lockInterruptibly();
            try {
                while (queue.size() == capacity) {
                    notFull.await();
                }
                queue.add(value);
                notEmpty.signal();
            } finally {
                lock.unlock();
            }
        }

        int take() throws InterruptedException {
            lock.lockInterruptibly();
            try {
                while (queue.isEmpty()) {
                    notEmpty.await();
                }
                int value = queue.remove();
                notFull.signal();
                return value;
            } finally {
                lock.unlock();
            }
        }
    }

    public static void main(String[] args) throws Exception {
        SafeCounter counter = new SafeCounter();
        int threads = 4;
        int rounds = 10_000;
        CountDownLatch done = new CountDownLatch(threads);
        for (int i = 0; i < threads; i++) {
            Thread worker = new Thread(() -> {
                for (int j = 0; j < rounds; j++) {
                    counter.incrementTwice();
                }
                done.countDown();
            }, "counter-" + i);
            worker.start();
        }
        done.await();
        System.out.println("counter=" + counter.get());
        assert counter.get() == threads * rounds * 2;

        ReentrantLock busy = new ReentrantLock();
        CountDownLatch locked = new CountDownLatch(1);
        Thread holder = new Thread(() -> {
            busy.lock();
            try {
                locked.countDown();
                Thread.sleep(180);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            } finally {
                busy.unlock();
            }
        }, "busy-holder");
        holder.start();
        locked.await();
        boolean acquired = busy.tryLock(80, TimeUnit.MILLISECONDS);
        System.out.println("tryLock while held=" + acquired);
        assert !acquired;
        if (acquired) {
            busy.unlock();
        }
        holder.join();

        ReentrantLock interruptible = new ReentrantLock();
        CountDownLatch waiting = new CountDownLatch(1);
        interruptible.lock();
        Thread waiter = new Thread(() -> {
            try {
                waiting.countDown();
                interruptible.lockInterruptibly();
                try {
                    throw new AssertionError("waiter should be interrupted before acquiring");
                } finally {
                    interruptible.unlock();
                }
            } catch (InterruptedException expected) {
                Thread.currentThread().interrupt();
                System.out.println("lockInterruptibly interrupted");
            }
        }, "interruptible-waiter");
        waiter.start();
        waiting.await();
        Thread.sleep(50);
        waiter.interrupt();
        waiter.join();
        interruptible.unlock();

        BoundedBox box = new BoundedBox(1);
        Thread consumer = new Thread(() -> {
            try {
                System.out.println("take=" + box.take());
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }, "box-consumer");
        consumer.start();
        Thread.sleep(50);
        box.put(42);
        consumer.join();
    }
}
